1	import { scoreArmy, type Card } from "./sphinx-score.js";
2	
3	type ArmyDocument = { army: Card[] };
4	
5	export const scoreDocument = (armyDocument: string): string => {
6	  const { army } = JSON.parse(armyDocument) as ArmyDocument;
7	  return JSON.stringify({ score: scoreArmy(army) });
8	};
9	
10	const readAll = async (input: AsyncIterable<string>): Promise<string> => {
11	  let document = "";
12	  for await (const chunk of input) document += chunk;
13	  return document;
14	};
15	
16	const runAsCommand = process.argv[1]?.endsWith("cli.ts") ?? false;
17	
18	if (runAsCommand) {
19	  process.stdin.setEncoding("utf8");
20	  readAll(process.stdin).then((document) => {
21	    process.stdout.write(scoreDocument(document));
22	  });
23	}
