1	import { describe, it, expect } from "vitest";
2	import { execFile } from "node:child_process";
3	import { scoreDocument } from "./cli.js";
4	
5	const runCli = (stdin: string): Promise<string> =>
6	  new Promise((resolve, reject) => {
7	    const cli = execFile(
8	      "pnpm",
9	      ["exec", "tsx", "src/cli.ts"],
10	      (error, stdout) => (error ? reject(error) : resolve(stdout)),
11	    );
12	    cli.stdin?.end(stdin);
13	  });
14	
15	describe("Sphinx scoring CLI", () => {
16	  it('scores an input document into an output document — {"army":[]} yields {"score":0}', () => {
17	    expect(scoreDocument('{"army":[]}')).toBe('{"score":0}');
18	  });
19	  it('delegates scoring to the army rules — the spec\'s example document yields {"score":2}', () => {
20	    const document =
21	      '{"army":[{"monster":"sphinx"},{"monster":"undead-warrior","rank":2},{"monster":"hydra"}]}';
22	
23	    expect(scoreDocument(document)).toBe('{"score":2}');
24	  });
25	  it("passes Undead Warrior rank through to the scorer — variants count as one type", () => {
26	    const document =
27	      '{"army":[{"monster":"sphinx"},' +
28	      '{"monster":"undead-warrior","rank":1},' +
29	      '{"monster":"undead-warrior","rank":2},' +
30	      '{"monster":"undead-warrior","rank":3},' +
31	      '{"monster":"cyclops"},{"monster":"orthrus"},{"monster":"chimera"}]}';
32	
33	    expect(scoreDocument(document)).toBe('{"score":3}');
34	  });
35	  it("runs as `pnpm exec tsx src/cli.ts`, reading stdin and writing the score to stdout", async () => {
36	    const document =
37	      '{"army":[{"monster":"sphinx"},{"monster":"undead-warrior","rank":2},{"monster":"hydra"}]}';
38	
39	    await expect(runCli(document)).resolves.toContain('{"score":2}');
40	  }, 60_000);
41	});
